function offsetElement(element, offset) {
  // Elementuaren offseta azaltzeko, elementua elementuaren amaieran sortu behar da.
  const clone = element.cloneNode(true);
  clone.style.position = 'absolute';
  clone.style.top = `${element.offsetTop - offset}px`;
  clone.style.left = `${element.offsetLeft}px`;
  clone.style.width = `${element.offsetWidth}px`;
  clone.style.height = `${element.offsetHeight}px`;
  clone.style.zIndex = '1';
  clone.style.opacity = '0.5'; // Ezabatzen diren elementuen kolorea alda dezakezu.
  clone.style.border = '1px solid black'; // Ezabatzen diren elementuen muga alda dezakezu.

  // Elementuaren amaieran sortu eta offseta azaltu.
  element.parentNode.appendChild(clone);
  return clone;
}

